//! Reproducible comparison benchmarks for PDFluent.
//!
//! These benchmarks operate on a synthetic 100-PDF, 50-page-each corpus
//! generated by `cargo run -p pdf-bench --bin gen-corpus --release`
//! (output: `/tmp/bench-corpus/`).  They are the source of truth for the
//! numbers published on pdfluent.com — see issue #271.
//!
//! Measured operations:
//!   * `merge/100x50pages` — `pdf_manip::pages::merge_documents` over all
//!     100 PDFs (5 000-page output).
//!   * `text_extract/50pages` — `pdf_extract::extract_text` on `doc_050.pdf`.
//!
//! Cold-start, peak-RSS, and idle-RSS measurements use the companion
//! binaries (`cold-start`, `merge-once`, `extract-once`, `idle-rss`) wrapped
//! by `/usr/bin/time -l`.  See `docs/benchmarks/methodology.md` in the
//! pdfluent-website repo for the full methodology.

use criterion::{criterion_group, criterion_main, Criterion, Throughput};
use lopdf::Document;
use std::path::{Path, PathBuf};
use std::time::Duration;

const CORPUS_DIR: &str = "/tmp/bench-corpus";

fn corpus_paths() -> Vec<PathBuf> {
    let dir = Path::new(CORPUS_DIR);
    let mut paths: Vec<PathBuf> = std::fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("read {CORPUS_DIR}: {e} — run `cargo run -p pdf-bench --bin gen-corpus --release` first"))
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|x| x == "pdf"))
        .collect();
    paths.sort();
    paths
}

fn load_corpus() -> Vec<Document> {
    corpus_paths()
        .iter()
        .map(|p| Document::load(p).expect("load corpus pdf"))
        .collect()
}

fn bench_merge(c: &mut Criterion) {
    let docs = load_corpus();
    assert!(!docs.is_empty(), "empty corpus — run gen-corpus first");

    let total_input_bytes: u64 = corpus_paths()
        .iter()
        .map(|p| std::fs::metadata(p).map(|m| m.len()).unwrap_or(0))
        .sum();

    let mut g = c.benchmark_group("merge");
    g.throughput(Throughput::Bytes(total_input_bytes));
    g.sample_size(50);
    g.measurement_time(Duration::from_secs(60));

    g.bench_function("100x50pages", |b| {
        b.iter(|| {
            let _ = pdf_manip::pages::merge_documents(&docs).expect("merge");
        });
    });

    g.finish();
}

fn bench_text_extract(c: &mut Criterion) {
    let path = Path::new(CORPUS_DIR).join("doc_050.pdf");
    let doc = Document::load(&path).unwrap_or_else(|e| panic!("load {}: {e}", path.display()));
    let bytes = std::fs::metadata(&path).map(|m| m.len()).unwrap_or(0);

    let mut g = c.benchmark_group("text_extract");
    g.throughput(Throughput::Bytes(bytes));
    g.sample_size(50);
    g.measurement_time(Duration::from_secs(30));

    g.bench_function("50pages", |b| {
        b.iter(|| {
            let _ = pdf_extract::extract_text(&doc);
        });
    });

    g.finish();
}

criterion_group!(comparison, bench_merge, bench_text_extract);
criterion_main!(comparison);
